<?php use Hls\Http\View as V; $e=fn($v)=>V::escape($v); $service=$printMode==='print-service'; ?><style>@page{size:A4;margin:14mm}body{background:#fff;color:#111}.print-sheet{font:12px Arial,sans-serif;max-width:190mm;margin:auto}.print-sheet h1{text-align:center;font-size:20px}.print-sheet h2{font-size:14px;border-bottom:1px solid #333;padding-bottom:3px}.print-meta{display:grid;grid-template-columns:1fr 1fr;gap:4px 20px}.print-table{width:100%;border-collapse:collapse;margin:8px 0}.print-table th,.print-table td{border:1px solid #555;padding:5px;text-align:left;vertical-align:top}.print-table th{background:#eee}.signatures{display:grid;grid-template-columns:1fr 1fr;gap:40px;margin-top:35px;text-align:center}.no-print{margin:12px 0}@media print{.no-print{display:none!important}tr{break-inside:avoid}.print-table thead{display:table-header-group}}</style><div class="no-print"><button type="button" onclick="window.print()">Cetak</button></div><article class="print-sheet"><header><img src="<?= $e($this->url('/assets/images/logo.png')) ?>" width="160" alt="HLS Transport"><h1><?= $service?'SERVICE REPORT':'WORK ORDER' ?></h1><p style="text-align:center">PT Hanqia Lintas Sarana</p></header><section class="print-meta"><div><strong>Nomor WO:</strong> <?= $e($row['wo_number']) ?></div><div><strong>Tanggal:</strong> <?= $e($row['created_at']) ?></div><div><strong>Unit:</strong> <?= $e($row['asset_code'].' — '.$row['asset_name']) ?></div><div><strong>Cabang:</strong> <?= $e($row['branch_name']) ?></div><div><strong>Status:</strong> <?= $e($row['status']) ?></div><div><strong>Jenis/Prioritas:</strong> <?= $e($row['work_type'].' / '.$row['priority']) ?></div><div><strong>HM/KM:</strong> <?= $e($row['hm_km']??'—') ?></div><div><strong>Lokasi:</strong> <?= $e($row['location']) ?></div></section><h2>Keluhan dan Pekerjaan</h2><p><?= nl2br($e($row['problem_description'])) ?></p><?php if($service): ?><p><strong>Diagnosis:</strong><br><?= nl2br($e($row['diagnosis']??'')) ?></p><p><strong>Tindakan:</strong><br><?= nl2br($e($row['repair_action']??'')) ?></p><?php endif ?><h2>Aktivitas</h2><table class="print-table"><thead><tr><th>Waktu</th><th>Pelaksana</th><th>Diagnosis</th><th>Tindakan/Catatan</th></tr></thead><tbody><?php foreach($activities as $a): ?><tr><td><?= $e($a['created_at']) ?></td><td><?= $e($a['actor_name']) ?></td><td><?= nl2br($e($a['diagnosis']??'')) ?></td><td><?= nl2br($e(($a['action_taken']??'')."\n".($a['notes']??''))) ?></td></tr><?php endforeach ?></tbody></table><h2>Spare Part</h2><table class="print-table"><thead><tr><th>Item</th><th>Dibutuhkan</th><th>Dikeluarkan</th></tr></thead><tbody><?php foreach($parts as $p): ?><tr><td><?= $e($p['item_code'].' — '.$p['item_name']) ?></td><td><?= $e($p['quantity_required'].' '.$p['unit_name']) ?></td><td><?= $e($p['quantity_issued'].' '.$p['unit_name']) ?></td></tr><?php endforeach ?></tbody></table><p><strong>Status HOLD:</strong> <?= $e(count(array_filter($holds,fn($h)=>!$h['released_at']))?'Aktif':'Tidak ada HOLD aktif') ?>. Penyelesaian WO tidak otomatis melepas HOLD.</p><p><strong>Mekanik:</strong> <?= $e($people['mechanic_name']??'Belum ditugaskan') ?><br><strong>Supervisor:</strong> <?= $e($people['supervisor_name']??'Belum ditugaskan') ?></p><div class="signatures"><div>Mekanik<br><br><br>____________________</div><div>Supervisor<br><br><br>____________________</div></div></article>
